def calculate_nutrition(food: dict[str, Any], grams: float) -> dict[str, Any]:
    grams = max(0.0, min(10000.0, float(grams)))
    scale = grams / 100.0
    return {"food": food["name"], "grams": round(grams, 1), "kcal": round(food["kcal"] * scale, 1), "kj": round(food["kj"] * scale, 1), "protein_g": round(food["protein"] * scale, 1), "fat_g": round(food["fat"] * scale, 1), "carbs_g": round(food["carbs"] * scale, 1), "fiber_g": round(food["fiber"] * scale, 1), "bread_units": round(food["he"] * scale, 2), "reference": "Ориентировочные усреднённые значения на 100 г; рецепт, сорт и обработка меняют состав. 1 ХЕ здесь условно 12 г усвояемых углеводов."}


def calculate_sleep_windows(wake_time: str, latency_min: int = 15) -> dict[str, Any]:
    from datetime import datetime, timedelta
    try:
        wake = datetime.strptime(wake_time, "%H:%M")
    except ValueError as exc:
        raise ValueError("Время укажите в формате ЧЧ:ММ") from exc
    latency = max(0, min(120, int(latency_min)))
    options = []
    for cycles in (4, 5, 6):
        bed = wake - timedelta(minutes=cycles * 90 + latency)
        options.append({"cycles": cycles, "bedtime": bed.strftime("%H:%M"), "sleep_hours": cycles * 1.5, "note": "Цикл 90 минут — упрощённое приближение, не индивидуальный прогноз."})
    return {"wake_time": wake_time, "options": options, "note": "Для большинства взрослых ориентир — регулярно не менее 7 часов сна; индивидуальная потребность различается. Это планировщик, не медицинская рекомендация."}


def calculate_flower_bouquet(stems: list[dict[str, Any]], wrapping: float = 8.0, labor: float = 12.0, markup_pct: float = 25.0) -> dict[str, Any]:
    normalized = []
    total = 0.0
    for row in stems[:30]:
        count = max(0, min(300, int(row.get("count", 0))))
        price = max(0.0, min(100000.0, float(row.get("price", 0))))
        line = round(count * price, 2)
        normalized.append({"name": str(row.get("name", "Цветок"))[:40], "count": count, "unit_price": price, "line_total": line})
        total += line
    direct = total + max(0.0, float(wrapping)) + max(0.0, float(labor))
    return {"items": normalized, "flowers": round(total, 2), "wrapping": round(max(0, wrapping), 2), "labor": round(max(0, labor), 2), "subtotal": round(direct, 2), "suggested_price": round(direct * (1 + max(0, min(300, markup_pct)) / 100), 2), "currency": "RUB", "note": "Примерная калькуляция. Используйте локальные закупочные цены; сезонность и доставка не учтены."}


